head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > E > onrightbuttonclick]<br/>트리 아이템의 아이콘 영역을 마우스 오른쪽 버튼으로 클릭할 때 발생합니다.",
    "validation" : [        
        "트리 아이템의 아이콘 영역을 마우스 오른쪽 버튼으로 클릭할 때 발생합니다.",                
        "node 파라미터로 클릭된 트리 아이템의 객체를 갖습니다.",
        "트리 아이템 객체의 속성을 통해 부모나 자식 트리 아이템에 접근할 수 있습니다.",        
        "node.checked 속성값으로 트리 아이템의 CheckBox 선택 상태값을 갖습니다.",
        "node.depth 속성값으로 트리 아이템의 Depth(단계)값을 갖습니다.",
        "node.depthIndex 속성값으로 형제(Sibling) 아이템을 기준으로 한 트리 아이템의 인덱스값을 갖습니다.",
        "node.folder 속성값으로 트리 아이템의 확장(false)/축소(true) 상태값을 갖습니다.",
        "트리 아이템이 Leaf 인 경우 node.folder 속성값으로 false 값을 갖습니다.",
        "node.index 속성값으로 트리 아이템의 인덱스값을 갖습니다.",
        "node.label 속성값으로 화면에 표시되는 라벨값이 아닌 트리 아이템의 Label 값을 갖습니다.",
        "node.value 속성값으로 트리 아이템의 Value 값을 갖습니다.",
        "node.parentNode 속성값으로 트리 아이템의 부모 아이템 객체를 갖습니다.",
        "node.childNodes 속성값으로 트리 아이템의 자식 아이템 객체를 배열로 갖습니다. ",
        "positionX 파라미터로 클릭된 위치의 마우스 X 좌표값을 갖습니다.",
        "topPosition 파라미터로 클릭된 위치의 마우스 Y 좌표값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        defaultImage : "/img/png.png",    
        expandedImage : "../../img/jpg.jpg",
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onrightbuttonclick"]);

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" dataType="listed" showCheckbox="true" style="position: relative;width: 200px;height: 350px;">';    
    strTarget += '<w2:itemset nodeset="data:dlt_Item">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref="folder"></w2:folder>';
    strTarget += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );
}



scwin.target1_onrightbuttonclick = function (node, positionX, topPosition) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onrightbuttonclick=====");

    wf_body_bottom.getObj("scwin").setReturnValue("node : " + node);

    if (node) {
        wf_body_bottom.getObj("scwin").setReturnValue("node.checked : " + node.checked);
        wf_body_bottom.getObj("scwin").setReturnValue("node.depth : " + node.depth);
        wf_body_bottom.getObj("scwin").setReturnValue("node.depthIndex : " + node.depthIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("node.folder : " + node.folder);
        wf_body_bottom.getObj("scwin").setReturnValue("node.index : " + node.index);
        wf_body_bottom.getObj("scwin").setReturnValue("node.label : " + node.label);
        wf_body_bottom.getObj("scwin").setReturnValue("node.value : " + node.value);
        wf_body_bottom.getObj("scwin").setReturnValue("node.parentNode.label : " + node.parentNode.label);
        wf_body_bottom.getObj("scwin").setReturnValue("node.childNodes.length : " + node.childNodes.length);           
    } 

    wf_body_bottom.getObj("scwin").setReturnValue("positionX : " + positionX);   
    wf_body_bottom.getObj("scwin").setReturnValue("topPosition : " + topPosition);   
}
